python - <<'PY'
import pathlib,re,gzip,subprocess
patterns = re.compile(rb'(?:AKIA|ASIA)[A-Z0-9]{16}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|hf_[A-Za-z0-9]{20,}|AIza[A-Za-z0-9_-]{30,}|sk-(?:proj-)?[A-Za-z0-9_-]{20,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----')
files=0
for p in pathlib.Path('.').rglob('*'):
 if not p.is_file() or '.git' in p.parts: continue
 files+=1
 b=p.read_bytes()
 if p.suffix=='.gz':
  try: b=gzip.decompress(b)
  except Exception: pass
 for m in patterns.finditer(b): print('Potential credential:',p,'line',b[:m.start()].count(b'\n')+1)
print('Scanned',files,'working-tree files (including gzip contents).')
commits=subprocess.check_output(['git','rev-list','--all']).splitlines()
print('Reachable commits:',len(commits))
for commit in commits:
 result=subprocess.run(['git','grep','-l','-E',r'AKIA1234567890123456|D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF|ghp_aBcDeFgHiJkLmNoPqRsTuVwXyZ0123456789|[REDACTED_HF_TOKEN_PATTERN]',commit.decode()],capture_output=True,text=True)
 if result.stdout: print('Original credentials remain in history:',result.stdout.strip())
